		font-size: 16px;
		font-weight: 500;
		color: #1e1e1e;
		margin: 0 0 2px 0;
	}

	.respondent-email {
		font-size: 14px;
		color: #757575;
		margin: 0;
		line-height: 1.4;
	}

	/* Metadata Section */
	.metadata-section {
