	}

	/* Form Fields */
	.form-fields {
		margin-top: 8px;
	}

	.form-fields-inner {
		padding: 16px 16px 24px;
	}

	.form-field {
		padding: 16px 0;
		border-bottom: 1px solid #F0F0F0;
	}

	.form-field:last-child {
		border-bottom: none;
	}

	.field-row {
		display: flex;
		align-items: flex-start;
	}

	.field-icon {
		width: 24px;
		height: 24px;
		margin-right: 16px;
		flex-shrink: 0;
		margin-top: 2px;
