		margin: 0 auto !important;
		max-width: 830px;
		padding: 0;
		padding-top: 24px;
		padding-bottom: 24px;
		width: 830px;
	}

	.content {
		box-sizing: border-box;
		display: block;
		margin: 0 auto;
		max-width: 830px;
		padding: 0;
	}

	.main {
		background: #ffffff;
		border-radius: 8px;
		width: 100%;
	}

	.wrapper {
		box-sizing: border-box;
		padding: 40px 48px;
	}

	.content-block {
		box-sizing: border-box;
		padding: 0 32px 24px;
	}

	.preheader {
		color: transparent;
		display: none;
		height: 0;
		max-height: 0;
		max-width: 0;
		opacity: 0;
		overflow: hidden;
		mso-hide: all;
		visibility: hidden;
		width: 0;
	}

	/* Header */
	.email-header {
		font-size: 20px;
		font-weight: 600;
		color: #1e1e1e;
		margin: 0 0 24px 0;
		padding: 0;
	}

	/* Respondent Info Section */
	.respondent-info {
		display: flex;
		align-items: center;
		margin-bottom: 24px;
		padding-bottom: 20px;
		border-bottom: 1px solid #E4E4E7;
	}

	.respondent-avatar {
		width: 48px;
		height: 48px;
		border-radius: 50%;
		background-color: #f0f0f0;
		display: flex;
		align-items: center;
		justify-content: center;
		font-size: 18px;
		font-weight: 600;
		color: #50575e;
		margin-right: 16px;
		flex-shrink: 0;
	}

	.respondent-avatar img {
		width: 48px;
		height: 48px;
		border-radius: 50%;
	}

	.respondent-details {
		flex: 1;
	}

	.respondent-name {
		font-size: 16px;
		font-weight: 500;
		color: #1e1e1e;
		margin: 0 0 2px 0;
	}

	.respondent-email {
		font-size: 14px;
		color: #757575;
		margin: 0;
		line-height: 1.4;
	}

	/* Metadata Section */
	.metadata-section {
		border-bottom: 1px solid #E4E4E7;
		padding: 16px 0;
		margin-bottom: 24px;
	}

	.metadata-table {
		width: 100%;
	}

	.metadata-table td {
		padding: 4px 0;
		font-size: 13px;
		vertical-align: top;
	}

	.metadata-label {
		color: #636363;
		width: 110px;
		padding-right: 12px;
	}

	.metadata-value {
		color: #1e1e1e;
	}

	.metadata-value a {
		color: #1e1e1e;
		text-decoration: underline;
	}

	/* Form Fields */
	.form-fields {
		margin-top: 8px;
	}

	.form-fields-inner {
		padding: 16px 16px 24px;
	}

	.form-field {
		padding: 16px 0;
		border-bottom: 1px solid #F0F0F0;
	}

	.form-field:last-child {
		border-bottom: none;
	}

	.field-row {
		display: flex;
		align-items: flex-start;
	}

	.field-icon {
		width: 24px;
		height: 24px;
		margin-right: 16px;
		flex-shrink: 0;
		margin-top: 2px;
	}

	.field-icon svg {
		width: 24px;
		height: 24px;
		fill: #50575e;
	}

	.field-content {
		flex: 1;
		min-width: 0;
	}

	.field-label {
		font-size: 12px;
		color: #757575;
		margin: 0 0 4px 0;
		text-transform: none;
	}

	.field-value {
		font-size: 13px;
		color: #1e1e1e;
		margin: 0;
		word-wrap: break-word;
	}

	.field-value a {
		color: #1e1e1e;
		text-decoration: underline;
	}

	/* Tag/Chip Styles for Multi-select */
	.field-tags {
