	/* Header */
	.email-header {
		font-size: 20px;
		font-weight: 600;
		color: #1e1e1e;
		margin: 0 0 24px 0;
		padding: 0;
	}

	/* Respondent Info Section */
	.respondent-info {
		display: flex;
