		width: 24px;
		height: 24px;
		margin-right: 16px;
		flex-shrink: 0;
		margin-top: 2px;
	}

	.field-icon svg {
		width: 24px;
		height: 24px;
		fill: #50575e;
	}

	.field-content {
		flex: 1;
		min-width: 0;
	}

	.field-label {
		font-size: 12px;
		color: #757575;
		margin: 0 0 4px 0;
		text-transform: none;
	}

	.field-value {
		font-size: 13px;
		color: #1e1e1e;
		margin: 0;
		word-wrap: break-word;
	}

	.field-value a {
		color: #1e1e1e;
		text-decoration: underline;
	}

	/* Tag/Chip Styles for Multi-select */
	.field-tags {
		display: flex;
		flex-wrap: wrap;
		gap: 6px;
		margin-top: 4px;
	}

	.field-tag {
		display: inline-block;
		background-color: #f0f0f0;
		border-radius: 2px;
		padding: 0 8px;
		font-size: 13px;
		color: #1e1e1e;
	}

	/* Image Select Styles */
	.image-choices {
		display: flex;
		flex-wrap: wrap;
		gap: 12px;
		margin-top: 8px;
	}

	.image-choice {
		text-align: center;
	}

	.image-choice img {
		width: 80px;
		height: 80px;
		object-fit: cover;
		border-radius: 4px;
		border: 1px solid #e0e0e0;
	}

	.image-choice-label {
		font-size: 12px;
		color: #50575e;
		margin-top: 4px;
	}

	/* Rating Styles */
	.rating-stars {
		color: #f5c518;
		font-size: 18px;
		letter-spacing: 2px;
	}

	/* File Upload Styles */
	.file-item {
		display: flex;
		align-items: center;
		gap: 8px;
		margin-top: 4px;
	}

	.file-icon {
		width: 16px;
		height: 16px;
		fill: #50575e;
	}

	.file-name {
		color: #1e1e1e;
		text-decoration: underline;
	}

	.file-size {
		color: #50575e;
		font-size: 12px;
	}

	/* Consent Chip */
	.consent-chip {
		display: inline-block;
		background-color: #d4edda;
		color: #155724;
		border-radius: 2px;
		padding: 0 8px;
		font-size: 13px;
	}

	.consent-chip.no {
		background-color: #f8d7da;
		color: #721c24;
	}

	/* Actions Section */
	.actions {
		margin-top: 24px;
		text-align: center;
	}

	.actions-table {
		width: 100%;
	}

	.action-button {
		display: inline-block;
		padding: 12px 24px;
		border-radius: 4px;
		font-size: 14px;
		font-weight: 500;
		text-decoration: none;
		margin: 0 6px;
	}

	.action-button-primary {
		background-color: #3858e9;
		color: #ffffff !important;
	}

	.action-button-secondary {
		background-color: transparent;
		color: #1e1e1e !important;
		border: 1px solid #1e1e1e;
	}

	/* Legacy Actions Support */
	.actions .button_block {
