		padding: 40px 48px;
	}

	.content-block {
		box-sizing: border-box;
		padding: 0 32px 24px;
	}

	.preheader {
		color: transparent;
		display: none;
		height: 0;
		max-height: 0;
		max-width: 0;
		opacity: 0;
		overflow: hidden;
		mso-hide: all;
		visibility: hidden;
		width: 0;
	}

	/* Header */
	.email-header {
		font-size: 20px;
		font-weight: 600;
		color: #1e1e1e;
		margin: 0 0 24px 0;
		padding: 0;
	}

	/* Respondent Info Section */
	.respondent-info {
		display: flex;
		align-items: center;
		margin-bottom: 24px;
		padding-bottom: 20px;
		border-bottom: 1px solid #E4E4E7;
	}

	.respondent-avatar {
		width: 48px;
		height: 48px;
		border-radius: 50%;
		background-color: #f0f0f0;
		display: flex;
		align-items: center;
		justify-content: center;
		font-size: 18px;
		font-weight: 600;
		color: #50575e;
		margin-right: 16px;
		flex-shrink: 0;
	}

	.respondent-avatar img {
		width: 48px;
		height: 48px;
		border-radius: 50%;
	}

	.respondent-details {
		flex: 1;
	}

	.respondent-name {
		font-size: 16px;
		font-weight: 500;
		color: #1e1e1e;
		margin: 0 0 2px 0;
	}

	.respondent-email {
		font-size: 14px;
		color: #757575;
		margin: 0;
		line-height: 1.4;
	}

	/* Metadata Section */
	.metadata-section {
		border-bottom: 1px solid #E4E4E7;
		padding: 16px 0;
		margin-bottom: 24px;
	}

	.metadata-table {
		width: 100%;
	}

	.metadata-table td {
		padding: 4px 0;
		font-size: 13px;
		vertical-align: top;
	}

	.metadata-label {
		color: #636363;
		width: 110px;
		padding-right: 12px;
	}

	.metadata-value {
		color: #1e1e1e;
	}

	.metadata-value a {
		color: #1e1e1e;
		text-decoration: underline;
	}

	/* Form Fields */
	.form-fields {
		margin-top: 8px;
	}

	.form-fields-inner {
		padding: 16px 16px 24px;
	}

	.form-field {
		padding: 16px 0;
		border-bottom: 1px solid #F0F0F0;
	}

	.form-field:last-child {
		border-bottom: none;
	}

	.field-row {
		display: flex;
		align-items: flex-start;
	}

	.field-icon {
		width: 24px;
		height: 24px;
		margin-right: 16px;
		flex-shrink: 0;
		margin-top: 2px;
	}

	.field-icon svg {
		width: 24px;
		height: 24px;
		fill: #50575e;
	}

	.field-content {
		flex: 1;
		min-width: 0;
	}

	.field-label {
		font-size: 15px;
		color: #757575;
		margin: 0 0 4px 0;
		text-transform: none;
	}

	.field-value {
		font-size: 16px;
		color: #1e1e1e;
		margin: 0;
		word-wrap: break-word;
	}

	.field-value a {
		color: #1e1e1e;
		text-decoration: underline;
	}

	/* Tag/Chip Styles for Multi-select */
	.field-tags {
		display: flex;
		flex-wrap: wrap;
		gap: 6px;
		margin-top: 4px;
	}

	.field-tag {
		display: inline-block;
		background-color: #f0f0f0;
		border-radius: 2px;
		padding: 0 8px;
		font-size: 16px;
		color: #1e1e1e;
	}

	/* Image Select Styles */
	.image-choices {
		display: flex;
		flex-wrap: wrap;
		gap: 12px;
		margin-top: 8px;
	}

	.image-choice {
		text-align: center;
	}

	.image-choice img {
		width: 80px;
		height: 80px;
		object-fit: cover;
		border-radius: 4px;
		border: 1px solid #e0e0e0;
	}

	.image-choice-label {
		font-size: 12px;
		color: #50575e;
		margin-top: 4px;
	}

	/* Rating Styles */
	.rating-stars {
		color: #f5c518;
		font-size: 18px;
		letter-spacing: 2px;
	}

	/* File Upload Styles */
	.file-item {
		display: flex;
		align-items: center;
		gap: 8px;
		margin-top: 4px;
	}

	.file-icon {
		width: 16px;
		height: 16px;
		fill: #50575e;
	}

	.file-name {
		color: #1e1e1e;
		text-decoration: underline;
	}

	.file-size {
		color: #50575e;
		font-size: 12px;
	}

	/* Consent Chip */
	.consent-chip {
		display: inline-block;
		background-color: #d4edda;
		color: #155724;
		border-radius: 2px;
		padding: 0 8px;
		font-size: 16px;
	}

	.consent-chip.no {
		background-color: #f8d7da;
		color: #721c24;
	}

	/* Actions Section */
	.actions {
		margin-top: 24px;
		text-align: center;
	}

	.actions-table {
		width: 100%;
	}

	.action-button {
		display: inline-block;
		padding: 12px 24px;
		border-radius: 4px;
		font-size: 14px;
		font-weight: 500;
		text-decoration: none;
		margin: 0 6px;
	}

	.action-button-primary {
		background-color: #3858e9;
		color: #ffffff !important;
	}

	.action-button-secondary {
		background-color: transparent;
		color: #1e1e1e !important;
		border: 1px solid #1e1e1e;
	}

	/* Legacy Actions Support */
	.actions .button_block {
		mso-table-lspace: 0pt;
		mso-table-rspace: 0pt;
		width: unset;
		margin-top: 24px;
	}

	.actions .button_block .pad,
	.actions .button_block .pad a {
		border-radius: 4px;
		background-image: url('https://s0.wordpress.com/i/emails/marketing/wpcom/2024/blueberry-px.png');
		background-size: cover;
		background-color: #3858E9;
	}

	.actions .button_block .pad a {
		font-size: 14px;
		font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif;
		font-weight: 500;
		text-decoration: none;
		padding: 12px 24px;
		color: #ffffff;
		border-radius: 4px;
		display: inline-block;
		mso-padding-alt: 0;
	}

	.actions .button_block .pad a span {
		mso-text-raise: 15pt;
	}

	.actions .button_block .pad i {
		letter-spacing: 25px;
		mso-font-width: -100%;
	}

	/* Footer */
	.footer {
		clear: both;
		padding: 24px 0;
		width: 100%;
	}

	.footer-content {
		text-align: center;
	}

	.footer td,
	.footer p,
	.footer span,
	.footer a {
		color: #50575e;
		font-size: 12px;
	}

	.powered-by {
		text-align: center;
		padding: 16px 0;
	}

	.powered-by a {
		color: #50575e;
		text-decoration: none;
		font-size: 12px;
	}

	.powered-by img {
